namespace AccessControl;

public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (TryGetContextDenial(principal, resource, request, out var denial))
            return denial;

        var access = BuildAccessContext(principal!, resource!, request!, delegations);

        if (request!.BreakGlass)
            return DecideBreakGlass(access.Administrator, request.StrongAuthentication);
        if (TryGetRestrictedResourceDenial(resource!, request, out denial))
            return denial;
        if (TryGetActionDenial(request.Action, access, out denial))
            return denial;

        return CreateApproval(resource, request, access.Delegated);
    }

    private static bool TryGetContextDenial(
        Principal? principal,
        Resource? resource,
        AccessRequest? request,
        out AccessDecision denial)
    {
        if (principal is null || resource is null || request is null)
            return Deny("missing-context", true, out denial);
        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
            return Deny("invalid-identity", true, out denial);
        if (principal.Suspended)
            return Deny("principal-suspended", true, out denial);
        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
            return Deny("tenant-mismatch", true, out denial);
        if (resource.Locked && request.Action != "read")
            return Deny("resource-locked", true, out denial);
        if (request.MinuteOfDay is < 0 or > 1439)
            return Deny("invalid-time", true, out denial);
        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
            return Deny("challenge-required", true, out denial);

        denial = default!;
        return false;
    }

    private static AccessContext BuildAccessContext(
        Principal principal,
        Resource resource,
        AccessRequest request,
        IDelegationRegister delegations)
    {
        var administrator = principal.Roles.Contains("administrator");
        var operatorRole = principal.Roles.Contains("operator");
        var auditor = principal.Roles.Contains("auditor");
        var owner = principal.Id == resource.OwnerId;
        var delegated = delegations.HasDelegation(principal.Id, resource.Id, request.Action);

        return new AccessContext(administrator, operatorRole, auditor, owner, delegated);
    }

    private static AccessDecision DecideBreakGlass(bool administrator, bool strongAuthentication)
    {
        if (!administrator || !strongAuthentication)
            return new AccessDecision(false, "invalid-break-glass", true);

        return new AccessDecision(true, "break-glass", true);
    }

    private static bool TryGetRestrictedResourceDenial(
        Resource resource,
        AccessRequest request,
        out AccessDecision denial)
    {
        if (resource.Classification == "restricted" && !request.StrongAuthentication)
            return Deny("strong-authentication-required", true, out denial);
        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
            return Deny("trusted-network-required", true, out denial);

        denial = default!;
        return false;
    }

    private static bool TryGetActionDenial(
        string action,
        AccessContext access,
        out AccessDecision denial)
    {
        switch (action)
        {
            case "delete":
                if (!access.Administrator)
                    return Deny("administrator-required", true, out denial);
                break;
            case "write":
                if (!access.CanWrite)
                    return Deny("write-not-authorised", true, out denial);
                break;
            case "read":
                if (!access.CanRead)
                    return Deny("read-not-authorised", false, out denial);
                break;
            default:
                return Deny("unknown-action", true, out denial);
        }

        denial = default!;
        return false;
    }

    private static AccessDecision CreateApproval(Resource resource, AccessRequest request, bool delegated)
    {
        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        return new AccessDecision(
            true,
            delegated ? "delegated" : "role-or-ownership",
            outsideBusinessHours || resource.Classification == "restricted");
    }

    private static bool Deny(string reason, bool auditRequired, out AccessDecision denial)
    {
        denial = new AccessDecision(false, reason, auditRequired);
        return true;
    }

    private readonly struct AccessContext
    {
        public AccessContext(
            bool administrator,
            bool operatorRole,
            bool auditor,
            bool owner,
            bool delegated)
        {
            Administrator = administrator;
            OperatorRole = operatorRole;
            Auditor = auditor;
            Owner = owner;
            Delegated = delegated;
        }

        public bool Administrator { get; }
        public bool OperatorRole { get; }
        public bool Auditor { get; }
        public bool Owner { get; }
        public bool Delegated { get; }
        public bool CanWrite => Administrator || OperatorRole || Owner || Delegated;
        public bool CanRead => Administrator || OperatorRole || Auditor || Owner || Delegated;
    }
}
